//   1=/CLR 9=CLK  D:4,5,12,13  Q:2,7,10,15  /Q:3,6,11,14
// --- 74ALS193  4-bit up/down binary counter ----------------------- К1533ИЕ7 --
//   15=A 1=B 10=C 9=D  11=/LOAD 14=CLR 5=UP 4=DOWN
//   3=QA 2=QB 6=QC 7=QD  12=/CARRY 13=/BORROW
